define([], function() {

    var STORAGE_KEY = 'local_profilephoto_camera_device';
    var FACING_STORAGE_KEY = 'local_profilephoto_camera_facing';
    var IDEAL_DIMENSION = 1280;
    var MAX_CAPTURE_DIMENSION = 1600;
    var JPEG_QUALITY = 0.92;

    var classifyError = function(error) {
        if (!window.isSecureContext) {
            return 'insecure';
        }
        switch (error && error.name) {
            case 'NotAllowedError':
            case 'SecurityError':
                return 'permission';
            case 'NotFoundError':
            case 'OverconstrainedError':
                return 'notfound';
            case 'NotReadableError':
            case 'TrackStartError':
                return 'inuse';
            default:
                return 'generic';
        }
    };

    var isSupported = function() {
        return Boolean(window.isSecureContext && navigator.mediaDevices && navigator.mediaDevices.getUserMedia);
    };

    var isFacingModeSupported = function() {
        return Boolean(
            navigator.mediaDevices &&
            navigator.mediaDevices.getSupportedConstraints &&
            navigator.mediaDevices.getSupportedConstraints().facingMode
        );
    };

    var createController = function(videoEl) {
        var stream = null;
        var currentDeviceId = null;
        var currentFacingMode = null;

        var stop = function() {
            if (stream) {
                stream.getTracks().forEach(function(track) {
                    track.stop();
                });
                stream = null;
            }
            videoEl.srcObject = null;
        };

        var listDevices = function() {
            if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
                return Promise.resolve([]);
            }
            return navigator.mediaDevices.enumerateDevices().then(function(devices) {
                return devices.filter(function(device) {
                    return device.kind === 'videoinput';
                });
            });
        };

        var start = function(deviceId, facingMode) {
            stop();

            var videoConstraints = {
                width: {ideal: IDEAL_DIMENSION},
                height: {ideal: IDEAL_DIMENSION},
            };
            if (deviceId) {
                videoConstraints.deviceId = {exact: deviceId};
            } else if (facingMode) {
                videoConstraints.facingMode = {ideal: facingMode};
            }

            return navigator.mediaDevices.getUserMedia({video: videoConstraints, audio: false}).then(function(mediastream) {
                stream = mediastream;
                currentDeviceId = deviceId || null;
                currentFacingMode = deviceId ? null : (facingMode || null);
                videoEl.srcObject = stream;

                if (deviceId) {
                    try {
                        window.localStorage.setItem(STORAGE_KEY, deviceId);
                    } catch (ignored) {
                        // Storage may be unavailable (private browsing); not critical.
                    }
                } else if (facingMode) {
                    try {
                        window.localStorage.setItem(FACING_STORAGE_KEY, facingMode);
                    } catch (ignored) {
                        // Storage may be unavailable (private browsing); not critical.
                    }
                }

                return videoEl.play();
            }).catch(function(error) {
                var wrapped = new Error('camera-error');
                wrapped.reason = classifyError(error);
                wrapped.cause = error;
                throw wrapped;
            });
        };

        var getRememberedDeviceId = function() {
            try {
                return window.localStorage.getItem(STORAGE_KEY);
            } catch (ignored) {
                return null;
            }
        };

        var getRememberedFacingMode = function() {
            try {
                return window.localStorage.getItem(FACING_STORAGE_KEY);
            } catch (ignored) {
                return null;
            }
        };

        var captureFrame = function() {
            if (!stream || !videoEl.videoWidth) {
                return Promise.reject(new Error('camera-not-active'));
            }

            var side = Math.min(videoEl.videoWidth, videoEl.videoHeight, MAX_CAPTURE_DIMENSION);
            var srcSide = Math.min(videoEl.videoWidth, videoEl.videoHeight);
            var srcX = (videoEl.videoWidth - srcSide) / 2;
            var srcY = (videoEl.videoHeight - srcSide) / 2;

            var canvas = document.createElement('canvas');
            canvas.width = side;
            canvas.height = side;
            var ctx = canvas.getContext('2d');
            ctx.drawImage(videoEl, srcX, srcY, srcSide, srcSide, 0, 0, side, side);

            return new Promise(function(resolve, reject) {
                canvas.toBlob(function(blob) {
                    if (blob) {
                        resolve(blob);
                    } else {
                        reject(new Error('capture-failed'));
                    }
                }, 'image/jpeg', JPEG_QUALITY);
            });
        };

        return {
            start: start,
            stop: stop,
            listDevices: listDevices,
            captureFrame: captureFrame,
            getRememberedDeviceId: getRememberedDeviceId,
            getRememberedFacingMode: getRememberedFacingMode,
            isActive: function() {
                return stream !== null;
            },
            getCurrentDeviceId: function() {
                return currentDeviceId;
            },
            getCurrentFacingMode: function() {
                return currentFacingMode;
            },
        };
    };

    return {
        isSupported: isSupported,
        isFacingModeSupported: isFacingModeSupported,
        createController: createController,
    };
});